content.problemStatement:
You are given a function,
int LeastDifference(int arr[], int length, int n);
int LeastDifference(int arr[], int length, int n);
static int LeastDifference(int[] arr, int n){}
static int LeastDifference(int[] arr, int n){]
def LeastDifference(arr, n):
The function accepts an integer array 'arr' of size 'length' and an integer 'n' as its arguments.
Implement the function to find and return the element of the array having least absolute difference
with the given number 'n'.
Assumption: Only 1 integer will have least absolute difference.
Note:
n >= 0
Absolute difference means you have to ignore the sign of the difference

code.C:
#include <stdio.h>
#include <stdlib.h>
int main() {
    int n; long long target; if (scanf("%d %lld", &n, &target) != 2) return 0;
    long long best_val = 0, min_diff = 2e18;
    for (int i = 0; i < n; i++) {
        long long x; scanf("%lld", &x);
        long long diff = llabs(x - target);
        if (i == 0 || diff < min_diff) { min_diff = diff; best_val = x; }
    }
    printf("%lld\n", best_val);
    return 0;
}

code.C++:
#include <iostream>
#include <cmath>
using namespace std;
int main() {
    int n; long long target; if (cin >> n >> target) {
        long long best_val = 0, min_diff = 2e18;
        for (int i = 0; i < n; i++) {
            long long x; cin >> x;
            long long diff = abs(x - target);
            if (i == 0 || diff < min_diff) { min_diff = diff; best_val = x; }
        }
        cout << best_val << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt(); long target = sc.nextLong();
            long bestVal = 0, minDiff = Long.MAX_VALUE;
            for (int i = 0; i < n; i++) {
                long x = sc.nextLong();
                long diff = Math.abs(x - target);
                if (i == 0 || diff < minDiff) { minDiff = diff; bestVal = x; }
            }
            System.out.println(bestVal);
        }
    }
}

